package org.sleepwell.app;

import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;

public final class MorningBarcodeTest {
    static final Map<String,String> VALUES=Map.of("EAN_13","5901234123457","EAN_8","96385074","UPC_A","042100005264","UPC_E","04252614","CODE_128","SLEEPWELL-42","CODE_39","MORNING-42");
    static byte[] pixels(BitMatrix matrix){byte[] image=new byte[matrix.getWidth()*matrix.getHeight()];for(int y=0;y<matrix.getHeight();y++)for(int x=0;x<matrix.getWidth();x++)image[y*matrix.getWidth()+x]=(byte)(matrix.get(x,y)?0:255);return image;}
    @Test public void everySupportedBarcodeDecodesActualGeneratedOriginalPixels()throws Exception{for(String format:MorningBarcode.FORMATS){String payload=VALUES.get(format);BitMatrix matrix=new MultiFormatWriter().encode(payload,BarcodeFormat.valueOf(format),640,240,Map.of(EncodeHintType.MARGIN,20));assertEquals(format,MorningBarcode.fingerprint(format,payload),new QrDecoder(format).digest(pixels(matrix),matrix.getWidth(),matrix.getHeight()));assertNull("QR-only reader must not enroll "+format,new QrDecoder().digest(pixels(matrix),matrix.getWidth(),matrix.getHeight()));}}
    @Test public void oneDimensionalCodesDecodeAcrossQuarterTurnsAndInversion()throws Exception{String format="CODE_128",payload=VALUES.get(format);BitMatrix matrix=new MultiFormatWriter().encode(payload,BarcodeFormat.CODE_128,640,240,Map.of(EncodeHintType.MARGIN,20));byte[] image=pixels(matrix);int width=640,height=240;for(int turn=0;turn<4;turn++){assertEquals(MorningBarcode.fingerprint(format,payload),new QrDecoder(format).digest(image,width,height));byte[] inverted=image.clone();for(int n=0;n<image.length;n++)inverted[n]=(byte)(255-(inverted[n]&255));assertEquals(MorningBarcode.fingerprint(format,payload),new QrDecoder(format).digest(inverted,width,height));byte[] rotated=new byte[image.length];for(int y=0;y<height;y++)for(int x=0;x<width;x++)rotated[x*height+height-1-y]=image[y*width+x];image=rotated;int swap=width;width=height;height=swap;}}
    @Test public void selectedFormatNeverFallsBackToUnrelatedCodeKinds()throws Exception{String payload="5901234123457";BitMatrix matrix=new MultiFormatWriter().encode(payload,BarcodeFormat.CODE_128,640,240);assertNull(new QrDecoder("EAN_13").digest(pixels(matrix),matrix.getWidth(),matrix.getHeight()));assertNotEquals(MorningBarcode.fingerprint("CODE_128",payload),MorningBarcode.fingerprint("EAN_13",payload));assertEquals(MorningCode.digest(payload),MorningBarcode.fingerprint(MorningBarcode.QR,payload));assertNotEquals(MorningCode.digest(payload),MorningBarcode.fingerprint("CODE_128",payload));}
    @Test public void exactTextAndLeadingZerosArePreserved(){assertEquals("042100005264",MorningBarcode.normalized("UPC_A","042100005264"));assertNotEquals(MorningBarcode.fingerprint("CODE_128","ABC"),MorningBarcode.fingerprint("CODE_128","ABC "));assertNotEquals(MorningBarcode.fingerprint("CODE_128","ABC"),MorningBarcode.fingerprint("CODE_128","abc"));}
    @Test public void invalidBoundsChecksumsUnsupportedAndUnencodableTextReject(){for(String format:MorningBarcode.FORMATS){assertThrows(IllegalArgumentException.class,()->MorningBarcode.normalized(format,""));assertThrows(IllegalArgumentException.class,()->MorningBarcode.normalized(format,"x".repeat(81)));}for(String bad:new String[]{"5901234123458"," 5901234123457","590123412345","٥٩٠١٢٣٤١٢٣٤٥٧"})assertThrows(IllegalArgumentException.class,()->MorningBarcode.normalized("EAN_13",bad));assertThrows(IllegalArgumentException.class,()->MorningBarcode.normalized("CODE_128","x\n"));assertThrows(IllegalArgumentException.class,()->MorningBarcode.normalized("CODE_39","lowercase"));assertThrows(IllegalArgumentException.class,()->new QrDecoder("PDF_417"));assertThrows(IllegalArgumentException.class,()->MorningBarcode.normalized(null,"ABC"));}
    @Test public void typedProofRejectsSameHashWithDifferentFormatAndStaleOccurrence(){String hash=MorningBarcode.fingerprint("CODE_128","MORNING-42");MorningCode code=new MorningCode("Bathroom",hash,MathSettings.LEGACY,"CODE_128");QrProof proof=new QrProof("run",1,"nonce",code);assertFalse(proof.consume("nonce","run",1,"CODE_128",hash,"CODE_39",hash,false,()->true));assertTrue(proof.consume("nonce","run",1,"CODE_128",hash,"CODE_128",hash,false,()->true));assertFalse(proof.consume("nonce","run",1,"CODE_128",hash,"CODE_128",hash,false,()->true));QrProof changed=new QrProof("run",1,"nonce",code);assertFalse(changed.consume("nonce","run",1,"CODE_39",hash,"CODE_128",hash,false,()->true));assertFalse(changed.consume("nonce","run",1,"CODE_128",hash,"CODE_128",hash,false,()->true));QrProof fallback=new QrProof("run",1,"nonce",code);assertTrue(fallback.consume("nonce","run",1,"CODE_128",hash,null,null,true,()->true));}
}
